use std::collections::HashSet;

fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::new();

    for x in nums {
        // `insert` returns true if `x` was not present in the set
        if seen.insert(x) {
            res.push(x);
        }
    }

    res
}

